svg.script:

(function() {
  const cards = document.querySelectorAll('.table-card');
  const paths = document.querySelectorAll('.relation-path');
  let selectedId = null;

  // Build relationship map
  const relations = {}; // tableId -> Set of related tableIds
  cards.forEach(card => {
    const id = card.getAttribute('data-table-id');
    relations[id] = new Set([id]);
  });

  paths.forEach(path => {
    const source = path.getAttribute('data-source');
    const target = path.getAttribute('data-target');
    if (relations[source]) {
      relations[source].add(target);
    }
    if (relations[target]) {
      relations[target].add(source);
    }
  });

  function applyHighlight(tableId) {
    if (!tableId) {
      cards.forEach(c => {
        c.classList.remove('dimmed');
        c.classList.remove('focused');
      });
      paths.forEach(p => {
        p.classList.remove('dimmed');
        p.classList.remove('highlighted');
      });
      return;
    }

    const related = relations[tableId] || new Set([tableId]);
    cards.forEach(c => {
      const id = c.getAttribute('data-table-id');
      if (related.has(id)) {
        c.classList.remove('dimmed');
        if (id === tableId) {
          c.classList.add('focused');
        } else {
          c.classList.remove('focused');
        }
      } else {
        c.classList.add('dimmed');
        c.classList.remove('focused');
      }
    });

    paths.forEach(p => {
      const source = p.getAttribute('data-source');
      const target = p.getAttribute('data-target');
      if (source === tableId || target === tableId) {
        p.classList.add('highlighted');
        p.classList.remove('dimmed');
      } else {
        p.classList.remove('highlighted');
        p.classList.add('dimmed');
      }
    });
  }

  cards.forEach(card => {
    card.addEventListener('click', (e) => {
      e.stopPropagation();
      const id = card.getAttribute('data-table-id');
      if (selectedId === id) {
        selectedId = null;
      } else {
        selectedId = id;
      }
      applyHighlight(selectedId);
    });

    card.addEventListener('mouseenter', () => {
      if (selectedId !== null) return;
      const id = card.getAttribute('data-table-id');
      applyHighlight(id);
    });

    card.addEventListener('mouseleave', () => {
      if (selectedId !== null) return;
      applyHighlight(null);
    });
  });

  // SVG background click resets selection
  document.addEventListener('click', (e) => {
    let clickedCard = false;
    let element = e.target;
    while (element) {
      if (element.classList && element.classList.contains('table-card')) {
        clickedCard = true;
        break;
      }
      element = element.parentNode;
    }
    if (!clickedCard) {
      selectedId = null;
      applyHighlight(null);
    }
  });
})();
